exercises.solution:
import java.util.ArrayList;

public class Above {
    public static ArrayList<Integer> aboveAverage(int[] nums) {
        ArrayList<Integer> out = new ArrayList<>();
        if (nums.length == 0) return out;
        double sum = 0;
        for (int n : nums) sum += n;
        double avg = sum / nums.length;
        for (int n : nums) if (n > avg) out.add(n);
        return out;
    }
}

